// Package inject replaces content between GEN markers in documentation files.
//
// Markers have the form:
//
//	<!-- GEN:<NAME>_START -->
//	<!-- DO NOT EDIT — auto-generated by make docs -->
//	<generated content>
//	<!-- GEN:<NAME>_END -->
//
// The InjectBetweenMarkers function replaces everything between START and END
// (exclusive) with a "DO NOT EDIT" comment followed by the replacement string.
package inject

import (
	"fmt"
	"os"
	"strings"
)

const doNotEditComment = "<!-- DO NOT EDIT — auto-generated by make docs -->"

// startMarker returns the START marker for a given name.
func startMarker(name string) string {
	return fmt.Sprintf("<!-- GEN:%s_START -->", name)
}

// endMarker returns the END marker for a given name.
func endMarker(name string) string {
	return fmt.Sprintf("<!-- GEN:%s_END -->", name)
}

// InjectBetweenMarkers replaces content between GEN markers with the given replacement.
// The START and END marker lines are preserved. A "DO NOT EDIT" comment is inserted
// as the first line after the START marker.
//
// Returns an error if:
//   - the START marker is missing
//   - the END marker is missing
//   - the END marker appears before the START marker
//   - the marker name is empty
func InjectBetweenMarkers(content, markerName, replacement string) (string, error) {
	if markerName == "" {
		return "", fmt.Errorf("marker name must not be empty")
	}

	start := startMarker(markerName)
	end := endMarker(markerName)

	startIdx := strings.Index(content, start)
	if startIdx < 0 {
		return "", fmt.Errorf("start marker %q not found", start)
	}

	endIdx := strings.Index(content, end)
	if endIdx < 0 {
		return "", fmt.Errorf("end marker %q not found", end)
	}

	if endIdx <= startIdx {
		return "", fmt.Errorf(
			"end marker appears at position %d, before or at start marker position %d",
			endIdx,
			startIdx,
		)
	}

	// Find the end of the START marker line (including newline).
	afterStart := startIdx + len(start)
	if afterStart < len(content) && content[afterStart] == '\n' {
		afterStart++
	}

	// Build the replacement block.
	var buf strings.Builder

	buf.WriteString(content[:afterStart])
	buf.WriteString(doNotEditComment)
	buf.WriteString("\n")

	trimmed := strings.TrimRight(replacement, "\n")
	if trimmed != "" {
		buf.WriteString(trimmed)
		buf.WriteString("\n")
	}

	buf.WriteString(content[endIdx:])

	return buf.String(), nil
}

// InjectFile reads a file, injects replacement content between markers, and writes it back.
func InjectFile(filePath, markerName, replacement string) error {
	data, err := os.ReadFile(filePath)
	if err != nil {
		return fmt.Errorf("reading %s: %w", filePath, err)
	}

	result, err := InjectBetweenMarkers(string(data), markerName, replacement)
	if err != nil {
		return fmt.Errorf("injecting into %s: %w", filePath, err)
	}

	if err := os.WriteFile(filePath, []byte(result), 0o600); err != nil {
		return fmt.Errorf("writing %s: %w", filePath, err)
	}

	return nil
}
